                        suffix_plus(ex, i + j, idx);
                        // ex.suffix(i+j).suffix(idx) == ex.suffix(i+j+idx)
                        // From always(next).satisfied_by(ex): next.satisfied_by(ex.suffix(i+j+idx))
                        assert(next.satisfied_by(ex.suffix(i + j + idx)));
